entries[27585] = { ["name"] = "Schwerer Obsidiangürtel", ["text"] = "Wirken in 1 min\nTools: Schmiedehammer\nReagenzien:\nKleiner Obsidiansplitter (14), Verzauberter Thoriumbarren (4), Essenz der Erde (2)\nSchwerer Obsidiangürtel\nWird beim Anlegen gebunden\nTaille Platte\n397 Rüstung\n+25 Stärke\nHaltbarkeit 45 / 45\n60\nAnlegen: +5 zu allen Widerstandsarten." }
entries[27586] = { ["name"] = "Gezackter Obsidianschild", ["text"] = "Wirken in 1 min\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (8), Kleiner Obsidiansplitter (24), Verzauberter Thoriumbarren (8), Essenz der Erde (4)\nGezackter Obsidianschild\nWird beim Anlegen gebunden\nSchildhand Schild\n2645 Rüstung\n48 Blocken\nHaltbarkeit 120 / 120\n60\nAnlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 2%.\nAnlegen: +5 zu allen Widerstandsarten.\nAnlegen: Bei einem Treffer durch einen gegnerischen Zauber besteht eine Chance von 5%, dass der Angreifer 3 Sek. lang zum Schweigen gebracht wird. (Procchance: 5%, 20s Abklingzeit)" }
entries[27587] = { ["name"] = "Dicke Obsidianbrustplatte", ["text"] = "Wirken in 1 min\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (18), Kleiner Obsidiansplitter (40), Verzauberter Thoriumbarren (12), Essenz der Erde (10), Gewaltiger Smaragd (4)\nDicke Obsidianbrustplatte\nWird beim Anlegen gebunden\nBrust Platte\n814 Rüstung\n+38 Stärke\n+16 Ausdauer\nHaltbarkeit 165 / 165\n60\nAnlegen: Bei einem Treffer durch einen Schadenszauber (mit Ausnahme von Zaubern mit regelmäßigem Schaden) besteht eine Chance von 30%, 6 Sek. lang einen Zauberschild zu aktivieren der 300 bis 500 Schaden der entsprechenden Schadenskategorie absorbiert. (Procchance: 30%, 10s Abklingzeit)" }
