entries[27589] = { ["name"] = "Dunkler Griff des Zerstörers", ["text"] = "Wirken in 1 min\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (8), Kleiner Obsidiansplitter (24), Verzaubertes Leder (8), Fläschchen mit oberster Macht\nDunkler Griff des Zerstörers\nWird beim Anlegen gebunden\nHände Kette\n279 Rüstung\nHaltbarkeit 50 / 50\n60\nAnlegen: +28 Angriffskraft.\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 1%.\nAnlegen: Bei einem erfolgreichen Nahkampf- oder Distanzangriff erhaltet Ihr 8 Mana, während dem Ziel 8 Mana entzogen werden." }
entries[27590] = { ["name"] = "Obsidianpanzertunika", ["text"] = "Wirken in 1 min\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (15), Kleiner Obsidiansplitter (36), Verzaubertes Leder (12), Wächterstein (10), Azerothianischer Diamant (4)\nObsidianpanzertunika\nWird beim Anlegen gebunden\nBrust Kette\n458 Rüstung\nHaltbarkeit 140 / 140\n60\nAnlegen: +76 Angriffskraft.\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 1%.\nAnlegen: Der erlittene Zauberschaden wird um 10 verringert." }
