entries[27605] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "470 Mana 30 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das 18 Sek. lang 852 Punkt(e) Schattenschaden zufügt." }
entries[27606] = { ["name"] = "Erneuerung", ["text"] = "365 Mana 40 Meter Reichweite\nSofort\nHeilt das Ziel 15 Sek. lang um 810 Schadenspunkt(e)." }
entries[27607] = { ["name"] = "Machtwort: Schild", ["text"] = "500 Mana 40 Meter Reichweite\nSofort 4 sek. Abklingzeit\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 942 Punkt(e) Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 Sek. lang nicht wieder abgeschirmt werden." }
