entries[27664] = { ["name"] = "Geschenk der Freundschaft von Stormwind", ["text"] = "Sofort\nReagenzien:\nKartenbündel , Brotsack mit hausgemachtem Brot , Pfandsammlung von Stormwind\nRechtsklicken, um aus einem Kartenbündel, einem Brotsack mit hausgemachtem Brot und einer Pfandsammlung von Stormwind eine Geschenkesammlung von Stormwind herzustellen." }
